pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);

        vm.prank(address(this));
        c.XBornID();

        vm.prank(alice);
        c.getTokens{value: 0}();

        vm.prank(alice);
        bool secondCallReverted;
        try c.getTokens{value: 0}() {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        assertTrue(secondCallReverted == true, "Second call should revert in reference, succeeds in bug");
    }
}
